# Find connected components of 4s using BFS
from collections import deque

visited = set()
components = []

def bfs(start):
    comp = [start]
    q = deque([start])
    visited.add(start)
    while q:
        r, c = q.popleft()
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < 30 and 0 <= nc < 12:
                if grid[nr][nc] == 4 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    comp.append((nr, nc))
                    q.append((nr, nc))
    return comp

for i in range(30):
    for j in range(12):
        if grid[i][j] == 4 and (i,j) not in visited:
            comp = bfs((i,j))
            components.append(comp)
            print(f"Component size {len(comp)}: {comp}")

print(f"\nTotal components: {len(components)}")

